// PowerUpSystem — pooled octahedra, color-coded by type.
// Types: RAPID · SPREAD · SHIELD · SLOW
// ===========================================================================
export const POWERUP_TYPES = {
  RAPID:  { color: 0x54f6ff, label: 'RAPID' },
  SPREAD: { color: 0xffd23c, label: 'SPREAD' },
