  spawn(type, x, y) {
    const slot = this.slots.find(s => !s.active);
    if (!slot) return false;
    slot.active = true;
    slot.type = type;
    slot.x = x;
    slot.y = y;
    const def = POWERUP_TYPES[type];
    slot.mat.emissive.setHex(def.color);
    slot.mesh.position.set(x, y, 0);
    slot.mesh.visible = true;
    return true;
  }

