  update(dt, playerX, playerY) {
    let collected = null;
    for (const s of this.slots) {
      if (!s.active) continue;
      s.y -= 6 * dt; // fall speed
      s.mesh.position.set(s.x, s.y, 0);
      s.mesh.rotation.y += dt * 3.2;
      s.mesh.rotation.x += dt * 1.7;

      if (s.y < 1) {
        s.active = false;
        s.mesh.visible = false;
