I'll track active items in a Set for O(1) release, and keep a free stack. Actually simpler: maintain an array of all items with an `active` flag, plus a freeStack of inactive indices. Let me do it cleanly:

```js
export class ObjectPool {
  constructor({ capacity = 8, create, reset }) {
    this.capacity = capacity;
    this.create = create;
    this.reset = reset || (() => {});
    this.items = new Array(capacity);
    for (let i = 0; i < capacity; i++) this.items[i] = create(i);
    this.freeStack = [];
    for (let i = capacity - 1; i >= 0; i--) this.freeStack.push(this.items[i]);
    this.activeCount = 0;
  }
  acquire() {
    if (!this.freeStack.length) return null;
    const item = this.freeStack.pop();
    item.active = true;
    this.reset(item);
    this.activeCount++;
    return item;
  }
  release(item) {
    if (!item.active) return;
    item.active = false;
    this.freeStack.push(item);
    this.activeCount--;
  }
  forEach(fn) {
    for (let i = 0; i < this.items.length; i++) {
      const it = this.items[i];
      if (it.active) fn(it, i);
    }
  }
}
```

That's clean and allocation-free in the hot path. Good.

