```js
export class ObjectPool {
  constructor({ factory, reset = () => {}, maxSize = Infinity }) {
    this.factory = factory;
    this.reset = reset;
    this.maxSize = maxSize;
    this.items = [];      // all created items (active + free)
    this.free = [];       // stack of inactive items
  }

  get activeCount() { return this.items.length - this.free.length; }

  acquire() {
    let item = this.free.pop();
    if (!item && this.items.length < this.maxSize) {
      item = this.factory();
      this.items.push(item);
    }
    if (item === undefined || item === null) return null;
    item.active = true;
    return item;
  }

  release(item) {
    if (!item || !item.active) return;
    item.active = false;
    this.reset(item);
    this.free.push(item);
  }

  forEachActive(fn) {
    for (let i = 0; i < this.items.length; i++) {
      const it = this.items[i];
      if (it.active) fn(it, i);
    }
  }

  releaseAll() { ... }
}
```

