  begin(target, duration) {
    // arbitration: strongest pending wins — if a new request comes during an active one with a lower target (stronger), take over.
    if (this.active && target >= this.target) return; // weaker than current → ignore
    this.fromScale = this.timescale;
    this.target = Math.max(0, target);
