    if (this.holdTime > 0) {
      this.holdTime -= dt;
      this.timescale = this.target;
      if (this.holdTime <= 0) { this.recoverTime = RECOVER; }
    } else if (this.recoverTime > 0) {
      const p = 1 - this.recoverTime / RECOVER; // 0→1
      const s = p * p * (3 - 2 * p); // smoothstep
      this.timescale = this.fromScale + (1 - this.fromScale) * s;
